CREATE TABLE `local_recovery_actions` (
	`workspace_id` text NOT NULL,
	`device_id` text NOT NULL,
	`epoch_id` text NOT NULL,
	`checkpoint_id` text NOT NULL,
	`descriptor` text NOT NULL,
	`local_descriptor` text NOT NULL,
	`created_at` integer NOT NULL,
	PRIMARY KEY(`workspace_id`, `device_id`, `epoch_id`, `checkpoint_id`),
	CONSTRAINT "local_recovery_actions_identity" CHECK(length(trim("local_recovery_actions"."workspace_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_actions"."workspace_id",char(0))=0 AND length(trim("local_recovery_actions"."device_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_actions"."device_id",char(0))=0 AND length(trim("local_recovery_actions"."epoch_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_actions"."epoch_id",char(0))=0 AND length(trim("local_recovery_actions"."checkpoint_id")) BETWEEN 1 AND 1000 AND instr("local_recovery_actions"."checkpoint_id",char(0))=0),
	CONSTRAINT "local_recovery_actions_descriptor" CHECK(json_valid("local_recovery_actions"."descriptor") AND json_type("local_recovery_actions"."descriptor",'$.version') IS 'integer' AND json_extract("local_recovery_actions"."descriptor",'$.version') IS 1 AND json_type("local_recovery_actions"."descriptor",'$.checkpoint.version') IS 'integer' AND json_extract("local_recovery_actions"."descriptor",'$.checkpoint.version') IS 1 AND json_type("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.version') IS 'integer' AND json_extract("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.version') IS 1 AND json_extract("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.identity.workspaceId') IS "local_recovery_actions"."workspace_id" AND json_extract("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.identity.deviceId') IS "local_recovery_actions"."device_id" AND json_extract("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.identity.epochId') IS "local_recovery_actions"."epoch_id" AND json_extract("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.identity.checkpointId') IS "local_recovery_actions"."checkpoint_id"),
	CONSTRAINT "local_recovery_actions_local_descriptor" CHECK(json_valid("local_recovery_actions"."local_descriptor") AND json_type("local_recovery_actions"."local_descriptor",'$.version') IS 'integer' AND json_extract("local_recovery_actions"."local_descriptor",'$.version') IS 1 AND json_extract("local_recovery_actions"."local_descriptor",'$.identity.workspaceId') IS "local_recovery_actions"."workspace_id" AND json_extract("local_recovery_actions"."local_descriptor",'$.identity.deviceId') IS "local_recovery_actions"."device_id" AND json_extract("local_recovery_actions"."local_descriptor",'$.identity.epochId') IS "local_recovery_actions"."epoch_id" AND json_extract("local_recovery_actions"."local_descriptor",'$.identity.checkpointId') IS "local_recovery_actions"."checkpoint_id" AND json_extract("local_recovery_actions"."local_descriptor",'$.identity.schemaId') IS json_extract("local_recovery_actions"."descriptor",'$.checkpoint.checkpoint.identity.schemaId'))
);
